import json, subprocess, sys, hashlib
sys.path.insert(0,'/workspace')
from wire import v, envelope, stream, crypto, datagram, trace

CLASSES='/workspace/tmp/classes'

def run(traces):
    inp=json.dumps({"traces":traces})
    p=subprocess.run(['python3','/workspace/run.py',CLASSES],input=inp.encode(),capture_output=True)
    if p.returncode!=0:
        raise SystemExit('nonzero exit %s %s'%(p.returncode,p.stderr.decode()[:2000]))
    return json.loads(p.stdout.decode())

def one(tr):
    r=run([tr])
    assert 'traces' in r, r
    return r['traces'][0]

def sha(b): return hashlib.sha256(b).hexdigest()

FAILURES=[]
def check(name, got, exp):
    if got!=exp:
        FAILURES.append((name,got,exp))
        print('FAIL',name)
        print('  got',json.dumps(got,sort_keys=True)[:600])
        print('  exp',json.dumps(exp,sort_keys=True)[:600])
    else:
        print('ok  ',name)

def status(t,i=0):
    return t['packets'][i]['status']

def summary(t):
    return t
